  <script>
    let lastRequest=null,lastQuote=null,assemblyParts=[],motionContract=null,motionHorizontal=0,motionVertical=0,hideDoors=false,ghostLexTop=false,assemblyViewMode='iso',assemblyColorMode='realistic',rotationDeg=215,dragging=false,lastDragX=0,threePromise=null,threeApi=null,threeState=null,instructionThreeState=null,instructionOverviewState=null,instructionOverviewCollapsed=false,instructionOverviewStepKey='',instructionLinked3d=false,instructionCameraSyncing=false,instructionSlideSequenceToken=0,instructionSlideOverviewDone=false,instructionSlideOverviewRunning=false,instructionSlidePendingDetail=null,modalSource=null,nestingZoom=1,nestingBaseWidth=0,nestingBaseHeight=0,catalogData=null,presentationData=null,instructionPlan=null,instructionStepIndex=0;
    const $=id=>document.getElementById(id);
    async function api(path,opts){const r=await fetch(path,opts),text=await r.text();let data=null;try{data=text?JSON.parse(text):null;}catch(e){}if(!r.ok)throw new Error((data&&(data.error||data.Error||data.message||data.Message))||text||('HTTP-fout '+r.status));return data;}
    function presentationObject(value,pascal,camel){return value&&(value[pascal]||value[camel])||null;}
    function presentationSection(name){const root=presentationObject(presentationData,'Assembly','assembly'),value=presentationObject(root,name[0].toUpperCase()+name.slice(1),name);if(!value)throw new Error('UI-presentatiecontract mist assembly.'+name+'.');return value;}
    function presentationNumber(section,key){const values=presentationSection(section),value=Number(values[key[0].toUpperCase()+key.slice(1)]??values[key]);if(!Number.isFinite(value)||value<=0)throw new Error('UI-presentatiecontract mist '+section+'.'+key+'.');return value;}
    function presentationColor(name){const tokens=presentationObject(presentationData,'DesignTokens','designTokens'),colors=presentationObject(tokens,'Colors','colors'),value=colors&&colors[name];if(!/^#[0-9a-f]{6}$/i.test(value||''))throw new Error('UI-presentatiecontract mist kleur '+name+'.');return value;}
    function presentationHex(name){return Number.parseInt(presentationColor(name).slice(1),16);}
    function applyPresentationContract(value){presentationData=value;const root=document.documentElement.style,colors={bg:'pageBackground',panel:'panel',ink:'text',muted:'mutedText',line:'divider',accent:'primaryAction',accent2:'success',warn:'warning',danger:'danger'};Object.entries(colors).forEach(([css,key])=>root.setProperty('--'+css,presentationColor(key)));}
    async function stopPortal(){const btn=document.querySelector('.stopPortal');if(btn){btn.disabled=true;btn.textContent='Stopt...';}try{const r=await api('/api/shutdown',{method:'POST'});document.body.innerHTML='<main style=""display:grid;place-items:center;min-height:100vh""><section class=""panel"" style=""max-width:520px;text-align:center""><h2>Portal gestopt</h2><p class=""muted"">'+r.message+'</p></section></main>';}catch(e){document.body.innerHTML='<main style=""display:grid;place-items:center;min-height:100vh""><section class=""panel"" style=""max-width:520px;text-align:center""><h2>Portal is gestopt</h2><p class=""muted"">Start de configurator opnieuw om verder te gaan.</p></section></main>';}}
    function productMeta(product){return catalogData&&catalogData.products?(catalogData.products.find(x=>x.Product===product)||null):null;}
    function catalogOption(id,profile){const source=profile?(catalogData&&catalogData.profiles||[]):(catalogData&&catalogData.sheets||[]),item=source.find(value=>value.Id===id);return{Value:id,Label:item&&item.Name?item.Name:'Onvolledige catalogusdata'};}
    function inputAttributes(input){const attrs=[];if(input.Minimum!==null&&input.Minimum!==undefined)attrs.push(`min=""${input.Minimum}""`);if(input.Maximum!==null&&input.Maximum!==undefined)attrs.push(`max=""${input.Maximum}""`);if(input.Step!==null&&input.Step!==undefined)attrs.push(`step=""${input.Step}""`);if(input.Required)attrs.push('required');return attrs.join(' ');}
    function renderInputControl(input){const id=input.InputId,request=input.RequestField,type=(input.InputType||'').toLowerCase(),value=input.DefaultValue==null?'':String(input.DefaultValue),attrs=inputAttributes(input);if(type==='checkbox'){const checked=/^(ja|true|1)$/i.test(value)?' checked':'';return `<div class=""contractField checkbox${input.BlocksConfiguration?' contractMissing':''}""><label><input id=""${id}"" type=""checkbox"" data-request-field=""${request}"" data-required=""${input.Required?'true':'false'}""${checked}> ${input.Label}</label><div class=""contractStatus"">${input.Status||''}</div></div>`;}if(type==='hidden')return `<input id=""${id}"" type=""hidden"" value=""${value}"" data-request-field=""${request}"" data-required=""${input.Required?'true':'false'}"">`;if(type==='select'){const options=(input.Options||[]).map(option=>`<option value=""${option.Value}""${String(option.Value)===value?' selected':''}>${option.Label}</option>`).join(''),placeholder=value||!input.Required?'':`<option value="""" selected disabled>Kies…</option>`;return `<div class=""contractField${input.BlocksConfiguration?' contractMissing':''}""><label for=""${id}"">${input.Label}${input.Unit?' '+input.Unit:''}</label><select id=""${id}"" data-request-field=""${request}"" data-required=""${input.Required?'true':'false'}"" ${attrs}>${placeholder}${options}</select><div class=""contractStatus"">${input.Status||''}</div></div>`;}return `<div class=""contractField${input.BlocksConfiguration?' contractMissing':''}""><label for=""${id}"">${input.Label}${input.Unit?' '+input.Unit:''}</label><input id=""${id}"" type=""number"" value=""${value}"" data-request-field=""${request}"" data-required=""${input.Required?'true':'false'}"" ${attrs}><div class=""contractStatus"">${input.Status||''}</div></div>`;}
    function renderConfigurationFields(meta){const host=$('configurationContractFields'),groups=new Map();(meta&&meta.ConfigurationInputs||[]).forEach(input=>{if(!groups.has(input.Section))groups.set(input.Section,[]);groups.get(input.Section).push(input);});host.innerHTML=[...groups.entries()].map(([section,inputs])=>`<section class=""contractSection"" data-contract-section=""${section}""><h3>${section.replace(/-/g,' ')}</h3><div class=""contractGrid"">${inputs.sort((a,b)=>a.Order-b.Order).map(renderInputControl).join('')}</div></section>`).join('');}
    function materialSelect(id,request,label,ids,profile,required){const options=(ids||[]).map(value=>catalogOption(value,profile)),placeholder=options.length===1?'':`<option value="""" selected disabled>Kies…</option>`;return `<div class=""contractField""><label for=""${id}"">${label}</label><select id=""${id}"" data-request-field=""${request}"" data-required=""${required?'true':'false'}""${required?' required':''}>${placeholder}${options.map(option=>`<option value=""${option.Value}"">${option.Label}</option>`).join('')}</select></div>`;}
    function renderMaterialFields(meta){const fields=[];if((meta.AllowedSheetMaterialIds||[]).length){fields.push(materialSelect('sheetMaterialId','SheetMaterialId','Plaatmateriaal',meta.AllowedSheetMaterialIds,false,true));if(meta.SupportsDrawers)fields.push(materialSelect('drawerMaterialId','DrawerMaterialId','Plaatmateriaal lades',meta.AllowedSheetMaterialIds,false,false));if(meta.SupportsBackPanel)fields.push(materialSelect('backMaterialId','BackMaterialId','Plaatmateriaal achterwand',meta.AllowedSheetMaterialIds,false,false));if(meta.SupportsDoors)fields.push(materialSelect('slidingDoorMaterialId','SlidingDoorMaterialId','Plaatmateriaal deuren',meta.AllowedSheetMaterialIds,false,false));}if((meta.AllowedProfileMaterialIds||[]).length)fields.push(materialSelect('profileMaterialId','ProfileMaterialId','Profielmateriaal',meta.AllowedProfileMaterialIds,true,true));$('materialContractFields').innerHTML=fields.length?`<section class=""contractSection""><h3>Materialen</h3><div class=""contractGrid"">${fields.join('')}</div></section>`:'';}
    function applyProductCatalogContract(meta){
      if(!meta)throw new Error('Productcontract ontbreekt in /api/catalog.');
      ['widthMm','depthMm','heightMm'].forEach(id=>{const el=$(id);el.removeAttribute('min');el.removeAttribute('max');el.removeAttribute('step');});
      (meta.InputConstraints||[]).forEach(rule=>{const el=$(rule.InputId);if(!el)return;el.min=String(rule.Minimum);el.max=String(rule.Maximum);});
      renderMaterialFields(meta);renderConfigurationFields(meta);
      const missing=meta.MissingConfigurationData||[],blockers=$('configurationBlockers');blockers.classList.toggle('active',missing.length>0);blockers.innerHTML=missing.length?'<strong>Configuratie geblokkeerd</strong><br>'+missing.map(value=>'• '+value).join('<br>'):'';
      applyReleaseContract(meta);applyExportContract(meta);
      $('generateBtn').disabled=!meta.CanConfigure;
    }
    function applyReleaseContract(meta){const panel=$('releaseStatus'),open=meta.OpenReleaseItems||[],concept=!meta.ProductionReleased;panel.classList.toggle('active',concept);panel.innerHTML=concept?'<strong>Conceptproduct — niet productievrijgegeven</strong><br>Renderen en de toegestane conceptbestanden exporteren mag. Open voor release:'+(open.length?'<ul>'+open.map(value=>'<li>'+value+'</li>').join('')+'</ul>':' geen geregistreerde punten.') : '';}
    function applyExportContract(meta){const allowed=new Set(meta.ConceptExportOutputs||[]),concept=!meta.ProductionReleased,map=[['exportIncludeCam','CAM'],['exportIncludeSolidWorks','SolidWorks'],['exportIncludeCustomerPackage','Klantvoorstel'],['exportIncludeInteractiveCustomerModel','Interactief 3D'],['exportIncludeHighDefinitionCustomerModel','High-definition 3D'],['exportIncludeThreeDPrint','3D-print'],['exportIncludeControls','Projectdata']];map.forEach(([id,label])=>{const input=$(id);if(!input)return;input.disabled=concept&&!allowed.has(label);input.checked=concept?allowed.has(label):true;});$('exportHint').textContent=concept?'Conceptexport: alleen de vrijgegeven basisbestanden; geen CAM of productievrijgave.':'Alleen de aangevinkte onderdelen komen in de projectmap';}
    function renderProductCards(products){const host=$('productChoices');if(!host)return;host.innerHTML=(products||[]).map((product,index)=>{const name=product.Name||product.Product||'Product',initials=name.split(/\s+/).filter(Boolean).slice(0,2).map(word=>word[0]).join('').toUpperCase();return `<button class=""choice"" type=""button"" data-product-index=""${index}""><div class=""choiceArt choiceGlyph"" aria-hidden=""true""><span>${initials}</span></div><div class=""choiceImageLabel"">${product.Category||''}</div><h3>${name}</h3><div class=""choiceStatus"">${product.Status||''}</div><span class=""choiceAction"">Open configurator</span></button>`;}).join('');host.querySelectorAll('[data-product-index]').forEach(button=>button.addEventListener('click',()=>{const product=(products||[])[Number(button.dataset.productIndex)];if(product)chooseProduct(product.Product);}));}
    function roundMm(value){return Math.round(value*10)/10;}
    function chooseProduct(product){document.body.classList.add('appOn');$('product').value=product;const meta=productMeta(product);if(!meta)throw new Error('Product ontbreekt in /api/catalog.');$('widthMm').value=meta.DefaultWidthMm;$('depthMm').value=meta.DefaultDepthMm;$('heightMm').value=meta.DefaultHeightMm;$('quantity').value=meta.DefaultQuantity;applyProductCatalogContract(meta);syncProductUi();if(meta.CanConfigure)quote();}
    function backToStart(){document.body.classList.remove('appOn');}
    function syncProductUi(){const meta=productMeta($('product').value);if(!meta)return;$('productName').textContent=meta.Name;$('widthLabel').textContent='Breedte mm';$('depthLabel').textContent='Diepte mm';$('heightLabel').textContent='Hoogte mm';$('generateBtn').textContent='Genereer product';$('solidWorksBtn').textContent=meta.ProductionReleased?'Exporteer projectpakket':'Exporteer conceptbasis';markDirty();$('generateBtn').disabled=!meta.CanConfigure;}
    function markDirty(){if($('orderBtn'))$('orderBtn').disabled=true;if($('mailQuoteBtn'))$('mailQuoteBtn').disabled=true;if($('solidWorksBtn'))$('solidWorksBtn').disabled=true;lastQuote=null;if($('dirtyNote'))$('dirtyNote').textContent='Instellingen gewijzigd. Genereer opnieuw voor actuele prijs en 3D assembly.';}
    function requestValue(element){if(element.type==='checkbox')return element.checked;const required=element.required||element.dataset.required==='true';if(required&&!element.value)throw new Error('Verplichte invoer ontbreekt: '+element.id+'.');if(element.type==='number'){if(element.value==='')return null;const value=Number(element.value);if(!Number.isFinite(value))throw new Error('Ongeldige numerieke invoer voor '+element.id+'.');return value;}return element.value;}
    function request(){const meta=productMeta($('product').value);if(!meta||!meta.CanConfigure)throw new Error((meta&&meta.MissingConfigurationData||['Productcontract ontbreekt.']).join(' '));const value={Product:$('product').value,WidthMm:requestValue($('widthMm')),DepthMm:requestValue($('depthMm')),HeightMm:requestValue($('heightMm')),Quantity:requestValue($('quantity')),CustomerName:$('customerName').value,ProjectName:$('projectName').value,CustomerEmail:$('customerEmail').value,CustomerPhone:$('customerPhone').value,Notes:$('notes').value};document.querySelectorAll('[data-request-field]').forEach(element=>{value[element.dataset.requestField]=requestValue(element);});return value;}
    async function loadCatalog(){const c=await api('/api/catalog');catalogData=c;applyPresentationContract(c.presentation);renderProductCards(c.products);}
